CREATE TABLE sla_policies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL,priority VARCHAR(32) NOT NULL,first_response_minutes INTEGER NOT NULL,resolution_minutes INTEGER NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT uk_sla_tenant_priority UNIQUE(tenant_id,priority),CONSTRAINT fk_sla_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id),CONSTRAINT ck_sla_priority CHECK(priority IN ('CRITICAL','HIGH','MEDIUM','LOW')),CONSTRAINT ck_sla_first_positive CHECK(first_response_minutes>0),CONSTRAINT ck_sla_resolution_positive CHECK(resolution_minutes>0));
ALTER TABLE tickets ADD COLUMN first_response_due_at TIMESTAMPTZ, ADD COLUMN resolution_due_at TIMESTAMPTZ, ADD COLUMN first_responded_at TIMESTAMPTZ, ADD COLUMN resolved_at TIMESTAMPTZ;
CREATE INDEX idx_tickets_tenant_resolution_due ON tickets(tenant_id,resolution_due_at);
